country_event = {
	id = envoy_events.215
	title = envoy_events.215.name
	desc = envoy_events.215.desc
	picture = GFX_evt_cover_blown
	show_sound = event_default

	is_triggered_only = yes

	trigger = {
		is_country_type = default
		is_gestalt = no
		any_owned_leader = {
			species = { is_robotic = no }
			OR = {
				AND = {
					is_assigned_to_federation = yes
					root.federation = {
						any_member = {
							NOR = {
								is_same_value = root
								is_same_species = root
								is_same_species = prevprev
								is_gestalt = yes
							}
						}
					}
				}
				AND = {
					is_assigned_to_galcom = yes
					any_country = {
						is_galactic_community_member = yes
						NOR = {
							is_same_value = root
							is_same_species = root
							is_same_species = prevprev
							is_gestalt = yes
						}
					}
				}
			}
			NOT = { has_leader_flag = respected_envoy }
		}
		NOT = { has_country_flag = recent_envoy_event }
	}

	immediate = {
		set_timed_country_flag = {
			flag = recent_envoy_event
			days = 5400
		}
		random_owned_leader = {
			limit = {
				species = { is_robotic = no }
				OR = {
					AND = {
						is_assigned_to_federation = yes
						root.federation = {
							any_member = {
								NOR = {
									is_same_value = root
									is_same_species = root
									is_same_species = prevprev
									is_gestalt = yes
								}
							}
						}
					}
					AND = {
						is_assigned_to_galcom = yes
						any_country = {
							is_galactic_community_member = yes
							NOR = {
								is_same_value = root
								is_same_species = root
								is_same_species = prevprev
								is_gestalt = yes
							}
						}
					}
				}
				NOT = { has_leader_flag = respected_envoy }
			}
			save_event_target_as = event_envoy

			if = {
				limit = {
					is_assigned_to_federation = yes
				}
				root.federation = {
					random_member = {
						limit = {
							NOR = {
								is_same_value = root
								is_same_species = root
								is_same_species = prevprev
								is_gestalt = yes
							}
						}
						save_event_target_as = provider_country
					}
				}
			}
			else = {
				random_country = {
					limit = {
						is_galactic_community_member = yes
						NOR = {
							is_same_value = root
							is_same_species = root
							is_same_species = prevprev
							is_gestalt = yes
						}
					}
					save_event_target_as = provider_country
				}
			}
		}
		set_espionage_diplo_incident_success_flag = {
			FLAG = substance_abuse
		}
	}

	option = {
		name = envoy_events.215.A
		custom_tooltip = envoy_events.215.A.tooltip
		hidden_effect = {
			event_target:event_envoy = {
				kill_leader = { show_notification = no }
			}
		}
		add_modifier = {
			modifier = diplo_corps_lost_control
			days = 3600
		}
	}

	option = {
		name = envoy_events.3.C1
		event_target:event_envoy = {
			unassign_leader = this
			add_trait = {
				trait = leader_trait_substance_abuser
			}
		}
	}
}

